expected "/*
 * Layer order, declared before any import so it is fixed for the whole bundle:
 *
 *   theme, base, components, utilities  — Tailwind + HeroUI, in their own order
 *   ob-tokens                          — OpenBot semantic values (`--ob-*`, both themes)
 *   ob-theme                           — HeroUI's published variables mapped onto them
 *   ob-legacy                          — the pre-migration shadcn names, deletion planned
 *   ob-app                             — app-level rules that used to be unlayered
 *
 * App declarations sit in layers ABOVE Tailwind's utilities rather than in no layer at all. An
 * unlayered rule outranks every layered one regardless of specificity, so an unlayered `input`
 * selector silently defeats `.text-sm`; that exact bug is still explained below. Layer order is
 * also why the theme bridge wins over HeroUI's `@layer base` defaults without `!important`.
 */
@layer theme, base, components, utilities, ob-tokens, ob-theme, ob-legacy, ob-app;

@import "tailwindcss";
/*
 * HeroUI, component by component.
 *
 * The full `@heroui/styles` entry ships every component's CSS (2.4 MB of source): it grew the
 * main stylesheet from 41 KB to 78 KB gzip, 74% over the A09 budget. Only these eight components
 * are HeroUI in H02; each later ticket adds its own imports as it migrates a wrapper. Shared
 * primitives (theme variables, base, utilities, variants) are always required.
 */
@import "@heroui/styles/base";
@import "@heroui/styles/base/scrollbar.css";
@import "@heroui/styles/themes/default";
@import "@heroui/styles/components/button.css";
@import "@heroui/styles/components/checkbox.css";
@import "@heroui/styles/components/input.css";
@import "@heroui/styles/components/label.css";
@import "@heroui/styles/components/separator.css";
@import "@heroui/styles/components/skeleton.css";
@import "@heroui/styles/components/switch.css";
@import "@heroui/styles/components/textarea.css";
@import "@heroui/styles/utilities";
@import "@heroui/styles/variants";
@import "tw-animate-css";
@import "shadcn/tailwind.css";
@import "@fontsource-variable/inter";

@import "./styles/tokens.css";
@import "./styles/heroui-theme.css";
@import "./styles/legacy-ui-bridge.css";

/*
 * Streamdown draws a Bot's prose, and Tailwind only ships classes it can see used. Its markup lives
 * in a dependency, so without this the transcript renders unstyled markdown — correct HTML with none
 * of the spacing that makes it readable. The path is relative to this file.
 *
 * Prompt Area is scanned directly for the same reason and for one more: the package's own
 * `prompt-area/tailwind.css` preset also declares FALLBACK `:root` tokens. Importing it would put
 * unlayered `--background`, `--primary` and friends back on the document, where they beat every
 * layered OpenBot value. Its class scanning is the only part the app needs, so the `@source`
 * replaces the preset and the token bridge in `styles/` stays authoritative.
 */
